INSERT INTO `qapi_queries` VALUES ('dia_estoque_rs','Universo de produtos ativos — estabelecimento RS (cod_estabe=2).','SELECT codigo AS `Código`, fornecedor AS `Fornecedor`, fabricante AS `Fabricante`, nome AS `Nome Produto`, categoria AS `Categoria`, dias_estoque AS `Dias de Estoque (Unidades)`, qtd_estoque AS `Qtd em Estoque`, venda_media_mes AS `Qtd Venda Média Mês`, custo_medio_liquido AS `Custo Medio Liquido`, valor_estoque_custo AS `Valor Estoque Custo`, data_ultima_compra AS `Data Última Compra`, lote AS `Lote`, validade_lote AS `Validade Lote`, estoque_lote AS `Estoque Lote`, data_ultima_transferencia AS `Data Ultima Transferencia`, qtd_venda_mes_atual AS `Qtd Venda Mes Atual`, qtd_venda_mes_anterior AS `Qtd Venda Mes Anterior`, qtd_venda_2m_anterior AS `Qtd Venda 2 Meses Anterior`, qtd_projetado_mes_atual AS `Qtd Projetado Mes Atual`, preco_politica AS `Preço Politica` FROM erp_produtos WHERE cod_estabe = 2',NULL,'2026-08-22 18:37:33'),('dia_estoque_sc','Universo de produtos ativos — estabelecimento SC (cod_estabe=1).','SELECT codigo AS `Código`, fornecedor AS `Fornecedor`, fabricante AS `Fabricante`, nome AS `Nome Produto`, categoria AS `Categoria`, dias_estoque AS `Dias de Estoque (Unidades)`, qtd_estoque AS `Qtd em Estoque`, venda_media_mes AS `Qtd Venda Média Mês`, custo_medio_liquido AS `Custo Medio Liquido`, valor_estoque_custo AS `Valor Estoque Custo`, data_ultima_compra AS `Data Última Compra`, lote AS `Lote`, validade_lote AS `Validade Lote`, estoque_lote AS `Estoque Lote`, data_ultima_transferencia AS `Data Ultima Transferencia`, qtd_venda_mes_atual AS `Qtd Venda Mes Atual`, qtd_venda_mes_anterior AS `Qtd Venda Mes Anterior`, qtd_venda_2m_anterior AS `Qtd Venda 2 Meses Anterior`, qtd_projetado_mes_atual AS `Qtd Projetado Mes Atual`, preco_politica AS `Preço Politica` FROM erp_produtos WHERE cod_estabe = 1',NULL,'2026-08-22 18:37:33'),('grupo_clientes_cnpj','Clientes de associativismo por CNPJ (1 grupo por cliente).','SELECT cnpj AS Cgc_Cpf, cod_grupo AS Cod_GrpCli, des_grupo AS Des_GrpCli FROM erp_grupo_clientes',NULL,'2026-08-22 18:37:33'),('pescador_3','Triagem/MC do Pescador (demo, estab. SC)','SELECT\n  CONCAT(\'789\', LPAD(codigo, 10, \'0\')) AS `Cod_EAN`,\n  \'88371\' AS `cod_polcom`,\n  88371 AS `id_polcom`,\n  \'SC\' AS `Estado_CliPag`,\n  codigo AS `codigo`,\n  nome AS `descricao`,\n  fabricante AS `fantasia`,\n  fornecedor AS `fornecedor`,\n  qtd_estoque AS `Estoque_Disponivel`,\n  CASE WHEN venda_media_mes >= 40 THEN \'A\' WHEN venda_media_mes >= 20 THEN \'B\' ELSE \'C\' END AS `Curva_ABC`,\n  ROUND(preco_politica, 4) AS `Preco Liquido`,\n  ROUND(preco_politica * 1.02, 4) AS `Preco Final`,\n  ROUND((preco_politica - custo_medio_liquido) / NULLIF(preco_politica, 0) * 100, 2) AS `Margem`,\n  ROUND(preco_politica / NULLIF(custo_medio_liquido, 0), 4) AS `Markup`,\n  NULL AS `ValorUltimaCompraComIPI`,\n  ROUND(preco_politica * 0.16, 4) AS `MC`,\n  0.1600 AS `Perc_MC`,\n  ROUND(venda_media_mes / NULLIF(qtd_estoque, 0), 4) AS `Giro_Estoque`,\n  ROUND(custo_medio_liquido, 4) AS `Vlr_CustoMedio`,\n  12.00 AS `Perc_ICMS_Aplicado`,\n  1.65 AS `Perc_PIS_Aplicado`,\n  7.60 AS `Perc_COFINS_Aplicado`,\n  1.50 AS `Perc_Comissao_Aplicada`,\n  0.50 AS `Perc_Frete_Aplicado`,\n  2.00 AS `Perc_Investimento_Empresa_Aplicado`,\n  1.00 AS `Perc_Associativismo_Aplicado`,\n  0.50 AS `Perc_Perdas_Vencidos_Aplicado`,\n  1.00 AS `Perc_Contratos_Aplicado`,\n  0.00 AS `Perc_Repasse_Aplicado`,\n  qtd_venda_mes_atual AS `Qtd_Vendida_Mes_Atual`,\n  qtd_venda_mes_anterior AS `Qtd_Vendida_Mes_Anterior`,\n  CASE WHEN qtd_venda_mes_atual > qtd_venda_mes_anterior THEN \'SUBIU VENDA\'\n       WHEN qtd_venda_mes_atual < qtd_venda_mes_anterior THEN \'CAIU VENDA\'\n       ELSE \'ESTAVEL\' END AS `Caiu/ Subiu venda`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 DAY), \'%Y-%m-%d\') AS `Data_DU_01`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 2 DAY), \'%Y-%m-%d\') AS `Data_DU_02`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 3 DAY), \'%Y-%m-%d\') AS `Data_DU_03`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 4 DAY), \'%Y-%m-%d\') AS `Data_DU_04`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 5 DAY), \'%Y-%m-%d\') AS `Data_DU_05`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 6 DAY), \'%Y-%m-%d\') AS `Data_DU_06`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 7 DAY), \'%Y-%m-%d\') AS `Data_DU_07`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 8 DAY), \'%Y-%m-%d\') AS `Data_DU_08`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 9 DAY), \'%Y-%m-%d\') AS `Data_DU_09`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 10 DAY), \'%Y-%m-%d\') AS `Data_DU_10`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 11 DAY), \'%Y-%m-%d\') AS `Data_DU_11`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 12 DAY), \'%Y-%m-%d\') AS `Data_DU_12`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 13 DAY), \'%Y-%m-%d\') AS `Data_DU_13`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 14 DAY), \'%Y-%m-%d\') AS `Data_DU_14`,\n  DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 15 DAY), \'%Y-%m-%d\') AS `Data_DU_15`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+0, 7)/10))) AS `Venda_DU_01`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+1, 7)/10))) AS `Venda_DU_02`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+2, 7)/10))) AS `Venda_DU_03`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+3, 7)/10))) AS `Venda_DU_04`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+4, 7)/10))) AS `Venda_DU_05`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+5, 7)/10))) AS `Venda_DU_06`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+6, 7)/10))) AS `Venda_DU_07`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+7, 7)/10))) AS `Venda_DU_08`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+8, 7)/10))) AS `Venda_DU_09`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+9, 7)/10))) AS `Venda_DU_10`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+10, 7)/10))) AS `Venda_DU_11`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+11, 7)/10))) AS `Venda_DU_12`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+12, 7)/10))) AS `Venda_DU_13`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+13, 7)/10))) AS `Venda_DU_14`,\n  GREATEST(0, FLOOR(venda_media_mes/22 * (0.5 + MOD(codigo+14, 7)/10))) AS `Venda_DU_15`,\n  lote AS `Cod_Lote_Venc_Proximo`,\n  estoque_lote AS `Qtd_Lote_Venc_Proximo`,\n  DATE_FORMAT(validade_lote, \'%Y-%m-%d\') AS `Data_Venc_Proximo`,\n  CASE WHEN validade_lote IS NULL THEN NULL\n       WHEN DATEDIFF(validade_lote, CURDATE()) < 90 THEN \'CRITICO\'\n       WHEN DATEDIFF(validade_lote, CURDATE()) < 180 THEN \'ATENCAO\'\n       ELSE \'OK\' END AS `Status_Validade_Lote_Proximo`,\n  \'CX C/1\' AS `Embalagem`\nFROM erp_produtos\nWHERE cod_estabe = 1 AND qtd_estoque > 0\nORDER BY venda_media_mes DESC\nLIMIT 60',NULL,'2026-08-22 19:00:48'),('qtd_pedido_cortado_layout','Pedidos CORTADOS do dia por rede/layout e estado.','SELECT layout AS `Layout`, estado AS Estado, SUM(qt_ped) AS Qt_Ped, SUM(vl_pedido) AS VALOR, MAX(dt_hora) AS DT_HORA FROM erp_pedidos_layout WHERE status = \'cortado\' GROUP BY layout, estado',NULL,'2026-08-22 18:37:33'),('qtd_pedido_dia','TOTAL de pedidos do dia (todos os status) por rede/layout e estado.','SELECT layout AS `Layout`, estado AS Estado, SUM(qt_ped) AS Qt_Ped FROM erp_pedidos_layout GROUP BY layout, estado',NULL,'2026-08-22 18:37:33'),('qtd_pedido_layout','Pedidos ACEITOS do dia agregados por rede/layout e estado.','SELECT layout AS `Layout`, estado, SUM(qt_ped) AS Qt_Ped, SUM(vl_pedido) AS Vl_pedido, MAX(dt_hora) AS DT_HORA FROM erp_pedidos_layout WHERE status = \'aceito\' GROUP BY layout, estado',NULL,'2026-08-22 18:37:33'),('venda_por_dia','Movimentação de venda por dia (parâmetros: cod_estabe, lista_produtos CSV).','SELECT cod_estabe, cod_produto, descricao_produto, data, qtd_venda, quantidade_saida, quantidade_entrada FROM erp_vendas WHERE cod_estabe = :cod_estabe AND cod_produto IN (:lista_produtos) ORDER BY cod_produto, data',NULL,'2026-08-22 18:37:33');
